// Narrow the depth of field of the active camera, then turn the blur on,
// so the characters stay sharp and the background goes soft.
local hCam = CMND_GET_ACT_CAMERA();
EV_TALK_DP_LVL_TMP = CMND_GET_CAMERA_PARAM(hCam, "DepthLevel");
CMND_DEPTHLEVEL_FADE(hCam, EV_TALK_DP_LVL, _frame);
CMND_DEPTHRANGE_FADE(hCam, 1.0, 1.5, _frame);
CMND_BOKE_CREATE(0.89999998, 7.0);
WaitFrame(_frame);
